fun e args cleanupAnnotations =>
  have e := e;
  have res := Array.mkEmpty args.size;
  have j := 0;
  do
  let __s ←
    forIn (*...args.size) (e, res, j) fun i __s =>
        have e := __s.1;
        have __s := __s.2;
        have res := __s.1;
        have j := __s.2;
        have __do_jp := fun __r e j =>
          match e with
          | Lean.Expr.forallE name type e' binderInfo =>
            have type := type.instantiateRevRange j i args;
            have type := if cleanupAnnotations = true then type.cleanupAnnotations else type;
            have res := res.push { name := name, type := type, binderInfo := binderInfo };
            have e := e';
            pure (ForInStep.yield (e, res, j))
          | x => do
            Lean.throwError
                (Lean.toMessageData "invalid `instantiateForallWithParams`, too many parameters" ++
                  Lean.toMessageData (Lean.indentExpr e))
            pure (ForInStep.yield (e, res, j));
        if e.isForall = true then __do_jp () e j
        else do
          let e ← Lean.Meta.whnf (e.instantiateRevRange j i args)
          have j : ℕ := i
          __do_jp () e j
  have e : Lean.Expr := __s.1
  have __s : Array Lean.Meta.ExprParamInfo × ℕ := __s.2
  have res : Array Lean.Meta.ExprParamInfo := __s.1
  pure (res, e)

