fun e isTarget => do
  let toReset ← liftM (IO.mkRef #[])
  let __do_lift ← Lean.instantiateMVars e
  Lean.Meta.forEachExpr __do_lift fun e =>
      if e.isApp = true then
        let args := e.getAppArgs;
        do
        forIn' (*...args.size) PUnit.unit fun i h __s =>
            have arg := args[i];
            if (arg.isMVar && isTarget.contains arg) = true then
              have mvarId := arg.mvarId!;
              do
              let __do_lift ← mvarId.getDecl
              if __do_lift.userName.isAnonymous = true then do
                  let __do_lift ← Lean.Meta.inferType e.getAppFn
                  Lean.Meta.forallBoundedTelescope __do_lift (some (i + 1)) fun xs x =>
                      if i < xs.size then
                        have mvarId := arg.mvarId!;
                        do
                        let __do_lift ← Lean.Meta.getFVarLocalDecl xs[i]!
                        let userName ← liftM (Lean.mkFreshUserName __do_lift.userName)
                        ST.Ref.modify toReset fun x => x.push mvarId
                        Lean.modifyMCtx fun mctx => mctx.setMVarUserNameTemporarily mvarId userName
                      else pure ()
                  pure (ForInStep.yield PUnit.unit)
                else pure (ForInStep.yield PUnit.unit)
            else pure (ForInStep.yield PUnit.unit)
        pure ()
      else pure ()
  ST.Ref.get toReset

