theorem String.mangleAux.eq_def✝ (s : String) (pos : s.Pos) (r : String) :
  String.mangleAux✝ s pos r =
    if h : pos = s.endPos then r
    else
      have c := pos.get h;
      have pos := pos.next h;
      if (c.isAlpha || c.isDigit) = true then String.mangleAux✝ s pos (r.push c)
      else
        if c = '_' then String.mangleAux✝ s pos (r ++ "__")
        else
          if c.toNat < 256 then String.mangleAux✝ s pos (String.pushHex✝ 2 c.val (r ++ "_x"))
          else
            if c.toNat < 65536 then String.mangleAux✝ s pos (String.pushHex✝ 4 c.val (r ++ "_u"))
            else String.mangleAux✝ s pos (String.pushHex✝ 8 c.val (r ++ "_U"))

theorem Lean.checkDisambiguation.eq_def✝ (s : String) (p : s.Pos) :
  Lean.checkDisambiguation✝ s p =
    if h : p ≠ s.endPos then
      have b := p.get h;
      if b = '_' then Lean.checkDisambiguation✝ s (p.next h)
      else
        if b = 'x' then Lean.checkLowerHex✝ 2 s (p.next h)
        else
          if b = 'u' then Lean.checkLowerHex✝ 4 s (p.next h)
          else
            if b = 'U' then Lean.checkLowerHex✝ 8 s (p.next h)
            else if (decide (b.val ≥ 48) && decide (b.val ≤ 57)) = true then true else false
    else true

theorem Lean.expandExternPatternAux.eq_def✝ (args : List String) (pattern : String) (it : pattern.Pos)
  (r : String) :
  Lean.expandExternPatternAux args pattern it r =
    if h : it.IsAtEnd then r
    else
      have c := it.get h;
      if c ≠ '#' then Lean.expandExternPatternAux args pattern (it.next h) (r.push c)
      else
        let it₁ := it.next h;
        match Lean.parseOptNum✝ (pattern.sliceFrom it₁) (pattern.sliceFrom it₁).startPos 0 with
        | (it₂, j) =>
          have j := j - 1;
          have this := ⋯;
          Lean.expandExternPatternAux args pattern (String.Pos.ofSliceFrom it₂)
            (r ++ args.getD j "")

theorem Lean.parseOptNum.eq_def✝ (pattern : String.Slice) (it : pattern.Pos) (r : ℕ) :
  Lean.parseOptNum✝ pattern it r =
    if h : it.IsAtEnd then (it, r)
    else
      have c := it.get h;
      if (decide ('0' ≤ c) && decide (c ≤ '9')) = true then
        Lean.parseOptNum✝ pattern (it.next h) (r * 10 + (c.toNat - '0'.toNat))
      else (it, r)

