fun stx =>
  have entriesStx := stx[1].getArgs;
  if (entriesStx.size == 0) = true then pure { entries := [Lean.ExternEntry.adhoc `all] }
  else
    have entries := #[];
    do
    let __s ←
      forIn entriesStx entries fun entryStx __s =>
          have entries := __s;
          have backend := if entryStx[0].isNone = true then `all else entryStx[0][0].getId;
          have __do_jp := fun str =>
            if entryStx[1].isNone = true then
              have entries := entries.push (Lean.ExternEntry.standard backend str);
              pure (ForInStep.yield entries)
            else
              have entries := entries.push (Lean.ExternEntry.inline backend str);
              pure (ForInStep.yield entries);
          match entryStx[2].isStrLit? with
          | none => do
            let str ← Lean.throwErrorAt entryStx[2] (Lean.toMessageData "string literal expected")
            __do_jp str
          | some str => do
            let str ← pure str
            __do_jp str
    have entries : Array Lean.ExternEntry := __s
    pure { entries := entries.toList }

